\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"oxlint\": \"1.81.0\",\n    \"oxlint-tsgolint\": \"7.0.2001\",\n    \"papaparse\": \"5.5.3\",\n    \"pnpm\": \"11.28.5\",\n    \"publint\": \"^0.3.24\",\n    \"semver\": \"^7.8.5\",\n    \"smol-toml\": \"^1.9.0\",\n    \"spdx-expression-parse\": \"^5.0.0\",\n    \"tar\": \"^7.5.22\",\n    \"tsdown\": \"^0.22.2\",\n    \"tsx\": \"^4.23.13\",\n    \"typescript\": \"^6.0.3\",\n    \"vite\": \"8.2.2\",\n    \"vite-tsconfig-paths\": \"^6.1.1\",\n    \"vitest\": \"^4.1.11\",\n    \"@deepseek-ai/dsh-skill-office\": \"workspace:*\",\n    \"@deepseek-ai/dsh-tool-workspace-dependencies\": \"workspace:*\",\n    \"@deepseek-ai/dsh-tool-working-directory\": \"workspace:*\",\n    \"@deepseek-ai/dsh-working-directory\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-worktree\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-tool-worktree\": \"workspace:*\",\n    \"@deepseek-ai/dsh-cua-bundle\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-subagent-oar\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-tool-subagent-oar\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-cua-macos\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-forge\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-forge-github\": \"workspace:*\",\n    \"@deepseek-ai/dsh-experimental-forge-session\": \"workspace:*\",\n    \"@deepseek-ai/dsh-action-cards\": \"workspace:*\"\n  }\n}\n"
